def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]

    opp_defects = sum(1 for m in opp_moves if m == 'D')
    my_defects = sum(1 for m in my_moves if m == 'D')

    opp_recent_defects = sum(1 for m in opp_moves[-10:] if m == 'D')
    my_recent_defects = sum(1 for m in my_moves[-10:] if m == 'D')

    if n >= 3:
        last_opp = opp_moves[-1]
        last_my = my_moves[-1]

        if last_opp == 'D' and last_my == 'C':
            if opp_recent_defects >= 2:
                return 'D'
            if rng.random() < 0.3:
                return 'D'
            return 'C'

        if last_opp == 'D' and last_my == 'D':
            if rng.random() < 0.4:
                return 'C'
            return 'D'

        if last_opp == 'C' and last_my == 'D':
            return 'C'

    total_rounds = 100
    remaining = total_rounds - n

    if n > 20 and opp_defects == 0:
        if remaining < 15 and my_defects == 0:
            if rng.random() < 0.8:
                return 'D'
        return 'C'

    if opp_defects / max(n, 1) > 0.6:
        return 'D'

    if opp_recent_defects >= 5:
        if rng.random() < 0.7:
            return 'D'

    if n >= 5:
        opp_last5 = opp_moves[-5:]
        if all(m == 'D' for m in opp_last5):
            if rng.random() < 0.5:
                return 'C'
            return 'D'

    if n >= 3 and opp_moves[-1] == 'C' and opp_moves[-2] == 'C' and opp_moves[-3] == 'C':
        if my_recent_defects == 0:
            return 'C'

    if remaining <= 3:
        if opp_defects == 0:
            return 'D'
        if opp_recent_defects >= 2:
            return 'D'
        return 'C'

    if n > 50:
        if opp_defects > my_defects + 3:
            if rng.random() < 0.4:
                return 'D'

    if n >= 10:
        recent = opp_moves[-10:]
        c_count = sum(1 for m in recent if m == 'C')
        if c_count >= 8:
            if remaining < 25 and rng.random() < 0.15:
                return 'D'
            return 'C'

    return 'C'

